CREATE TABLE IF NOT EXISTS intelligence_profiles (id integer PRIMARY KEY AUTOINCREMENT NOT NULL, enq_no text NOT NULL, company_json text NOT NULL, digital_footprint_json text NOT NULL, behavioral_traits_json text NOT NULL, confidence text DEFAULT 'PRELIMINARY' NOT NULL, reviewed integer DEFAULT false NOT NULL, generated_at text DEFAULT CURRENT_TIMESTAMP NOT NULL, FOREIGN KEY (enq_no) REFERENCES leads(enq_no));
CREATE TABLE IF NOT EXISTS proposal_intelligence (id integer PRIMARY KEY AUTOINCREMENT NOT NULL, enq_no text NOT NULL, markdown text NOT NULL, project_framework text NOT NULL, estimated_basic_value real DEFAULT 0 NOT NULL, updated_at text DEFAULT CURRENT_TIMESTAMP NOT NULL, FOREIGN KEY (enq_no) REFERENCES leads(enq_no));
CREATE TABLE IF NOT EXISTS social_snapshots (id integer PRIMARY KEY AUTOINCREMENT NOT NULL, channel text NOT NULL, captured_at text NOT NULL, reach integer DEFAULT 0 NOT NULL, followers integer DEFAULT 0 NOT NULL, engagement_rate real DEFAULT 0 NOT NULL, payload_json text DEFAULT '{}' NOT NULL);
